<?php declare(strict_types=1);final class TaskEventRepository{public function __construct(private mysqli$db){}public function append(array$d):void{$s=$this->db->prepare('INSERT INTO TaskEvents(task_id_,step_id_,execution_id_,actor_type,actor_user_id_,event_key,from_status,to_status,summary,details_json) VALUES(?,?,?,?,?,?,?,?,?,?)');if(!$s)throw new RuntimeException('database_error');$step=$d['step_id']??null;$execution=$d['execution_id']??null;$actor=$d['actor_user_id']??null;$from=$d['from_status']??null;$to=$d['to_status']??null;$json=isset($d['details'])?json_encode($d['details'],JSON_THROW_ON_ERROR):null;$s->bind_param('iiisisssss',$d['task_id'],$step,$execution,$d['actor_type'],$actor,$d['event_key'],$from,$to,$d['summary'],$json);if(!$s->execute())throw new RuntimeException('database_error');$s->close();}public function listOwned(int$task,int$u):array{$s=$this->db->prepare('SELECT e.actor_type,e.event_key,e.from_status,e.to_status,e.summary,e.details_json,e.created_at FROM TaskEvents e JOIN Tasks t ON t.id_=e.task_id_ WHERE e.task_id_=? AND t.user_id_=? ORDER BY e.id_');if(!$s)throw new RuntimeException('database_error');$s->bind_param('ii',$task,$u);$s->execute();$o=[];$r=$s->get_result();while($x=$r->fetch_assoc())$o[]=$x;$s->close();return$o;}}
